// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// v2 changes from the original ArcPool/ArcFactoryV2 (audit findings addressed):
// 1. Restored the MINIMUM_SHARES lock on first liquidity deposit — this was
//    present in the original ArcFactory (V1) but had been dropped here,
//    reopening the classic first-depositor pool-inflation attack.
// 2. Added a nonReentrant guard on addLiquidity/removeLiquidity/swap. This
//    factory is permissionless — anyone can pair ANY ERC20 token, including
//    a malicious one with reentrant transfer hooks — so, unlike ArcSwap or
//    ArcAMM (which only ever touch trusted USDC/EURC), external calls here
//    genuinely need a reentrancy guard, not just careful ordering.
contract ArcPool {
    address public immutable tokenA;
    address public immutable tokenB;
    address public immutable factory;

    uint256 public reserveA;
    uint256 public reserveB;
    uint256 public totalShares;
    mapping(address => uint256) public shares;

    uint256 constant FEE_BPS = 30; // 0.3%
    uint256 constant BPS_DENOM = 10000;
    uint256 constant MINIMUM_SHARES = 1000;

    uint256 private locked; // reentrancy guard: 0 = unlocked, 1 = locked

    event LiquidityAdded(address indexed provider, uint256 amountA, uint256 amountB, uint256 sharesMinted);
    event LiquidityRemoved(address indexed provider, uint256 amountA, uint256 amountB, uint256 sharesBurned);
    event Swap(address indexed trader, bool aToB, uint256 amountIn, uint256 amountOut);

    modifier nonReentrant() {
        require(locked == 0, "Reentrancy blocked");
        locked = 1;
        _;
        locked = 0;
    }

    constructor(address _tokenA, address _tokenB) {
        tokenA = _tokenA;
        tokenB = _tokenB;
        factory = msg.sender;
    }

    function addLiquidity(uint256 amountA, uint256 amountB) external nonReentrant returns (uint256 mintedShares) {
        require(amountA > 0 && amountB > 0, "Amounts must be > 0");

        if (totalShares == 0) {
            mintedShares = sqrt(amountA * amountB);
            require(mintedShares > MINIMUM_SHARES, "Initial liquidity too small");
            mintedShares -= MINIMUM_SHARES;
            shares[address(0)] += MINIMUM_SHARES;
            totalShares += MINIMUM_SHARES;
        } else {
            uint256 shareA = (amountA * totalShares) / reserveA;
            uint256 shareB = (amountB * totalShares) / reserveB;
            mintedShares = shareA < shareB ? shareA : shareB;
            require(mintedShares > 0, "Insufficient liquidity minted");
        }

        reserveA += amountA;
        reserveB += amountB;
        shares[msg.sender] += mintedShares;
        totalShares += mintedShares;

        require(IERC20(tokenA).transferFrom(msg.sender, address(this), amountA), "TokenA transfer failed");
        require(IERC20(tokenB).transferFrom(msg.sender, address(this), amountB), "TokenB transfer failed");

        emit LiquidityAdded(msg.sender, amountA, amountB, mintedShares);
    }

    function removeLiquidity(uint256 shareAmount) external nonReentrant returns (uint256 amountA, uint256 amountB) {
        require(shareAmount > 0 && shareAmount <= shares[msg.sender], "Invalid share amount");

        amountA = (shareAmount * reserveA) / totalShares;
        amountB = (shareAmount * reserveB) / totalShares;
        require(amountA > 0 && amountB > 0, "Insufficient reserves");

        shares[msg.sender] -= shareAmount;
        totalShares -= shareAmount;
        reserveA -= amountA;
        reserveB -= amountB;

        require(IERC20(tokenA).transfer(msg.sender, amountA), "TokenA transfer failed");
        require(IERC20(tokenB).transfer(msg.sender, amountB), "TokenB transfer failed");

        emit LiquidityRemoved(msg.sender, amountA, amountB, shareAmount);
    }

    // Constant product swap: (x + dx*0.997) * (y - dy) = x * y
    function swap(bool aToB, uint256 amountIn, uint256 minAmountOut) external nonReentrant returns (uint256 amountOut) {
        require(amountIn > 0, "Amount must be > 0");
        require(reserveA > 0 && reserveB > 0, "No liquidity");

        uint256 amountInWithFee = amountIn * (BPS_DENOM - FEE_BPS);

        if (aToB) {
            uint256 numerator = amountInWithFee * reserveB;
            uint256 denominator = (reserveA * BPS_DENOM) + amountInWithFee;
            amountOut = numerator / denominator;
            require(amountOut >= minAmountOut, "Slippage too high");
            require(amountOut < reserveB, "Insufficient pool liquidity");

            reserveA += amountIn;
            reserveB -= amountOut;

            require(IERC20(tokenA).transferFrom(msg.sender, address(this), amountIn), "TokenA transfer failed");
            require(IERC20(tokenB).transfer(msg.sender, amountOut), "TokenB transfer failed");
        } else {
            uint256 numerator = amountInWithFee * reserveA;
            uint256 denominator = (reserveB * BPS_DENOM) + amountInWithFee;
            amountOut = numerator / denominator;
            require(amountOut >= minAmountOut, "Slippage too high");
            require(amountOut < reserveA, "Insufficient pool liquidity");

            reserveB += amountIn;
            reserveA -= amountOut;

            require(IERC20(tokenB).transferFrom(msg.sender, address(this), amountIn), "TokenB transfer failed");
            require(IERC20(tokenA).transfer(msg.sender, amountOut), "TokenA transfer failed");
        }

        emit Swap(msg.sender, aToB, amountIn, amountOut);
    }

    function getAmountOut(bool aToB, uint256 amountIn) external view returns (uint256 amountOut) {
        if (reserveA == 0 || reserveB == 0) return 0;
        uint256 amountInWithFee = amountIn * (BPS_DENOM - FEE_BPS);
        if (aToB) {
            uint256 numerator = amountInWithFee * reserveB;
            uint256 denominator = (reserveA * BPS_DENOM) + amountInWithFee;
            amountOut = numerator / denominator;
        } else {
            uint256 numerator = amountInWithFee * reserveA;
            uint256 denominator = (reserveB * BPS_DENOM) + amountInWithFee;
            amountOut = numerator / denominator;
        }
    }

    function getReserves() external view returns (uint256, uint256) {
        return (reserveA, reserveB);
    }

    function getShareValue(address provider) external view returns (uint256 amountA, uint256 amountB) {
        if (totalShares == 0) return (0, 0);
        amountA = (shares[provider] * reserveA) / totalShares;
        amountB = (shares[provider] * reserveB) / totalShares;
    }

    function sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

// Factory: anyone can permissionlessly create a swap-enabled pool for any
// ERC20 token pair on Arc Testnet.
contract ArcFactoryV2 {
    address[] public allPools;
    mapping(address => mapping(address => address)) public getPool;

    event PoolCreated(address indexed tokenA, address indexed tokenB, address pool);

    function createPool(address tokenA, address tokenB) external returns (address pool) {
        require(tokenA != tokenB, "Identical tokens");
        require(tokenA != address(0) && tokenB != address(0), "Zero address");
        require(getPool[tokenA][tokenB] == address(0), "Pool already exists");

        ArcPool newPool = new ArcPool(tokenA, tokenB);
        pool = address(newPool);

        getPool[tokenA][tokenB] = pool;
        getPool[tokenB][tokenA] = pool;
        allPools.push(pool);

        emit PoolCreated(tokenA, tokenB, pool);
    }

    function allPoolsLength() external view returns (uint256) {
        return allPools.length;
    }
}

contracts/ArcLaunchPoolFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// Same low-level-call pattern as ArcFactoryV2_v4's SafeERC20 — handles
// non-standard tokens (like real USDT) that return no data on
// transfer/transferFrom instead of reverting on the strict interface.
library SafeERC20 {
    function safeTransfer(IERC20 token, address to, uint256 amount) internal {
        (bool success, bytes memory data) = address(token).call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "SafeERC20: transfer failed");
    }

    function safeTransferFrom(IERC20 token, address from, address to, uint256 amount) internal {
        (bool success, bytes memory data) = address(token).call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "SafeERC20: transferFrom failed");
    }
}

// A minimal read-only view into ArcTokenFactoryV2 — just enough to confirm
// a token was genuinely minted through it (launchedAt != 0 for a real
// launched token, 0 for anything else, including a malicious token someone
// deploys by hand to spoof this check).
interface IArcTokenFactory {
    function launchedAt(address token) external view returns (uint256);
}

// Identical AMM logic to ArcFactoryV2_v4's ArcPool (same fee, same
// MINIMUM_SHARES first-deposit lock, same reentrancy guard, same
// balanceOf-delta accounting for fee-on-transfer/rebase tokens, same
// SafeERC20 usage) — deliberately not reinvented. The only thing that's
// different in this file is who's allowed to deploy a new instance of it
// (see ArcLaunchPoolFactory below), not how the pool itself behaves.
contract ArcPool {
    using SafeERC20 for IERC20;

    address public immutable tokenA;
    address public immutable tokenB;
    address public immutable factory;

    uint256 public reserveA;
    uint256 public reserveB;
    uint256 public totalShares;
    mapping(address => uint256) public shares;

    uint256 constant FEE_BPS = 30; // 0.3%
    uint256 constant BPS_DENOM = 10000;
    uint256 constant MINIMUM_SHARES = 1000;

    uint256 private locked;

    event LiquidityAdded(address indexed provider, uint256 amountA, uint256 amountB, uint256 sharesMinted);
    event LiquidityRemoved(address indexed provider, uint256 amountA, uint256 amountB, uint256 sharesBurned);
    event Swap(address indexed trader, bool aToB, uint256 amountIn, uint256 amountOut);
    event Synced(uint256 reserveA, uint256 reserveB);

    modifier nonReentrant() {
        require(locked == 0, "Reentrancy blocked");
        locked = 1;
        _;
        locked = 0;
    }

    constructor(address _tokenA, address _tokenB) {
        tokenA = _tokenA;
        tokenB = _tokenB;
        factory = msg.sender;
    }

    // v2 change (matches ArcFactoryV2 v4c's own addLiquidity, per the real
    // interface already used successfully against live v4c pools elsewhere
    // in this app — LiquidityPools.tsx's V4C_POOL_ABI): takes desired +
    // minimum amounts on both sides (standard Uniswap V2 Router pattern)
    // and pulls only the ratio-matching amount instead of the full desired
    // amount, so excess tokens are never silently donated to the pool.
    // This is NOT the same signature as ArcFactoryV2_v4.sol's addLiquidity
    // (amountA, amountB, deadline — 3 args) — ArcTokenFactoryV2's
    // lockLaunchLiquidity() calls the 5-arg version below specifically,
    // confirmed by decoding the exact selector (0xa360501c) it sent from a
    // live reverted transaction. An earlier version of this file copied
    // the 3-arg v4 signature by mistake, which made every pool created by
    // this factory permanently un-lockable — lockLaunchLiquidity would
    // revert every time, with no funds moved, since the pool had no
    // function matching what it was calling.
    function addLiquidity(uint256 amountADesired, uint256 amountBDesired, uint256 amountAMin, uint256 amountBMin, uint256 deadline) external nonReentrant returns (uint256 mintedShares) {
        require(block.timestamp <= deadline, "Transaction expired");

        uint256 amountA;
        uint256 amountB;
        if (totalShares == 0) {
            require(amountADesired > 0 && amountBDesired > 0, "Amounts must be > 0");
            amountA = amountADesired;
            amountB = amountBDesired;
        } else {
            uint256 amountBOptimal = (amountADesired * reserveB) / reserveA;
            if (amountBOptimal <= amountBDesired) {
                require(amountBOptimal >= amountBMin, "Insufficient B amount");
                amountA = amountADesired;
                amountB = amountBOptimal;
            } else {
                uint256 amountAOptimal = (amountBDesired * reserveA) / reserveB;
                require(amountAOptimal <= amountADesired, "Excessive A amount");
                require(amountAOptimal >= amountAMin, "Insufficient A amount");
                amountA = amountAOptimal;
                amountB = amountBDesired;
            }
        }

        uint256 balanceABefore = IERC20(tokenA).balanceOf(address(this));
        uint256 balanceBBefore = IERC20(tokenB).balanceOf(address(this));
        IERC20(tokenA).safeTransferFrom(msg.sender, address(this), amountA);
        IERC20(tokenB).safeTransferFrom(msg.sender, address(this), amountB);
        uint256 actualA = IERC20(tokenA).balanceOf(address(this)) - balanceABefore;
        uint256 actualB = IERC20(tokenB).balanceOf(address(this)) - balanceBBefore;
        require(actualA > 0 && actualB > 0, "No tokens received");

        if (totalShares == 0) {
            mintedShares = sqrt(actualA * actualB);
            require(mintedShares > MINIMUM_SHARES, "Initial liquidity too small");
            mintedShares -= MINIMUM_SHARES;
            shares[address(0)] += MINIMUM_SHARES;
            totalShares += MINIMUM_SHARES;
        } else {
            uint256 shareA = (actualA * totalShares) / reserveA;
            uint256 shareB = (actualB * totalShares) / reserveB;
            mintedShares = shareA < shareB ? shareA : shareB;
            require(mintedShares > 0, "Insufficient liquidity minted");
        }

        reserveA += actualA;
        reserveB += actualB;
        shares[msg.sender] += mintedShares;
        totalShares += mintedShares;

        emit LiquidityAdded(msg.sender, actualA, actualB, mintedShares);
    }

    function removeLiquidity(uint256 shareAmount, uint256 deadline) external nonReentrant returns (uint256 amountA, uint256 amountB) {
        require(block.timestamp <= deadline, "Transaction expired");
        require(shareAmount > 0 && shareAmount <= shares[msg.sender], "Invalid share amount");

        amountA = (shareAmount * reserveA) / totalShares;
        amountB = (shareAmount * reserveB) / totalShares;
        require(amountA > 0 && amountB > 0, "Insufficient reserves");

        shares[msg.sender] -= shareAmount;
        totalShares -= shareAmount;
        reserveA -= amountA;
        reserveB -= amountB;

        IERC20(tokenA).safeTransfer(msg.sender, amountA);
        IERC20(tokenB).safeTransfer(msg.sender, amountB);

        emit LiquidityRemoved(msg.sender, amountA, amountB, shareAmount);
    }

    function swap(bool aToB, uint256 amountIn, uint256 minAmountOut, uint256 deadline) external nonReentrant returns (uint256 amountOut) {
        require(block.timestamp <= deadline, "Transaction expired");
        require(amountIn > 0, "Amount must be > 0");
        require(reserveA > 0 && reserveB > 0, "No liquidity");

        if (aToB) {
            uint256 balanceBefore = IERC20(tokenA).balanceOf(address(this));
            IERC20(tokenA).safeTransferFrom(msg.sender, address(this), amountIn);
            uint256 actualIn = IERC20(tokenA).balanceOf(address(this)) - balanceBefore;

            uint256 amountInWithFee = actualIn * (BPS_DENOM - FEE_BPS);
            uint256 numerator = amountInWithFee * reserveB;
            uint256 denominator = (reserveA * BPS_DENOM) + amountInWithFee;
            amountOut = numerator / denominator;
            require(amountOut >= minAmountOut, "Slippage too high");
            require(amountOut < reserveB, "Insufficient pool liquidity");

            reserveA += actualIn;
            reserveB -= amountOut;

            IERC20(tokenB).safeTransfer(msg.sender, amountOut);
        } else {
            uint256 balanceBefore = IERC20(tokenB).balanceOf(address(this));
            IERC20(tokenB).safeTransferFrom(msg.sender, address(this), amountIn);
            uint256 actualIn = IERC20(tokenB).balanceOf(address(this)) - balanceBefore;

            uint256 amountInWithFee = actualIn * (BPS_DENOM - FEE_BPS);
            uint256 numerator = amountInWithFee * reserveA;
            uint256 denominator = (reserveB * BPS_DENOM) + amountInWithFee;
            amountOut = numerator / denominator;
            require(amountOut >= minAmountOut, "Slippage too high");
            require(amountOut < reserveA, "Insufficient pool liquidity");

            reserveB += actualIn;
            reserveA -= amountOut;

            IERC20(tokenA).safeTransfer(msg.sender, amountOut);
        }

        emit Swap(msg.sender, aToB, amountIn, amountOut);
    }

    function sync() external nonReentrant {
        uint256 actualA = IERC20(tokenA).balanceOf(address(this));
        uint256 actualB = IERC20(tokenB).balanceOf(address(this));
        if (actualA < reserveA) reserveA = actualA;
        if (actualB < reserveB) reserveB = actualB;
        emit Synced(reserveA, reserveB);
    }

    function getAmountOut(bool aToB, uint256 amountIn) external view returns (uint256 amountOut) {
        if (reserveA == 0 || reserveB == 0) return 0;
        uint256 amountInWithFee = amountIn * (BPS_DENOM - FEE_BPS);
        if (aToB) {
            uint256 numerator = amountInWithFee * reserveB;
            uint256 denominator = (reserveA * BPS_DENOM) + amountInWithFee;
            amountOut = numerator / denominator;
        } else {
            uint256 numerator = amountInWithFee * reserveA;
            uint256 denominator = (reserveB * BPS_DENOM) + amountInWithFee;
            amountOut = numerator / denominator;
        }
    }

    function getReserves() external view returns (uint256, uint256) {
        return (reserveA, reserveB);
    }

    function getShareValue(address provider) external view returns (uint256 amountA, uint256 amountB) {
        if (totalShares == 0) return (0, 0);
        amountA = (shares[provider] * reserveA) / totalShares;
        amountB = (shares[provider] * reserveB) / totalShares;
    }

    function sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

// Permissionless — BUT ONLY for (a genuinely launched token, USDC) pairs.
// This exists so a token creator isn't stuck waiting for the FlowFi owner
// to manually open a pool before their token is tradeable at all, without
// reopening ArcFactoryV2 v4's createPool() itself back up (that one stays
// onlyOwner, for curated pools like USDC/EURC/cirBTC — this factory is a
// separate, narrower trust boundary that doesn't touch it).
//
// The only thing stopping this from being pure spam-a-pool-for-any-token:
// tokenA must satisfy IArcTokenFactory.launchedAt(tokenA) != 0, i.e. it was
// actually minted through ArcTokenFactoryV2's launchToken(), not just any
// ERC20 someone deployed to look similar. tokenB is hardcoded to USDC —
// there's no way to call this for an arbitrary pair.
//
// NOTE before relying on this for mainnet: ArcTokenFactoryV2's
// lockLaunchLiquidity(token, pool, ...) — the function a creator calls to
// permanently lock their initial liquidity — takes the pool address as a
// caller-supplied parameter. Whether it validates that pool came from a
// specific trusted factory (e.g. checking pool.factory() against a known
// address) isn't visible from here, since ArcTokenFactoryV2's source isn't
// available (only verified bytecode). If it does, pools from THIS factory
// may need to be allowlisted there too, or lockLaunchLiquidity could reject
// them. Test this end-to-end on testnet — launch a token, create its pool
// here, then try lockLaunchLiquidity with it — before trusting this path
// for a real launch.
contract ArcLaunchPoolFactory {
    address public immutable tokenFactory;
    address public immutable usdc;

    address[] public allPools;
    mapping(address => address) public getPool; // launched token => pool

    event LaunchPoolCreated(address indexed token, address pool);

    constructor(address _tokenFactory, address _usdc) {
        require(_tokenFactory != address(0) && _usdc != address(0), "Zero address");
        tokenFactory = _tokenFactory;
        usdc = _usdc;
    }

    function createLaunchPool(address token) external returns (address pool) {
        require(token != address(0) && token != usdc, "Invalid token");
        require(getPool[token] == address(0), "Pool already exists");
        require(IArcTokenFactory(tokenFactory).launchedAt(token) != 0, "Not a token launched through ArcTokenFactoryV2");

        ArcPool newPool = new ArcPool(token, usdc);
        pool = address(newPool);

        getPool[token] = pool;
        allPools.push(pool);

        emit LaunchPoolCreated(token, pool);
    }

    function allPoolsLength() external view returns (uint256) {
        return allPools.length;
    }
}

contracts/ArcLending.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// v2 changes from the original ArcLending (audit findings addressed):
// 1. Added a minimal "guardian" role that can ONLY pause/unpause new
//    borrowing — it cannot withdraw funds, change interest parameters, or
//    touch anyone's position. This exists specifically for a stablecoin
//    depeg scenario (this contract assumes USDC/EURC are both ~$1 with no
//    oracle) — if that assumption ever breaks, new borrowing can be frozen
//    while supply/repay/withdraw/liquidate all remain fully open, so no
//    user is ever trapped by the pause itself.
// 2. Reordered external calls to happen AFTER state updates
//    (Checks-Effects-Interactions) in supply/depositCollateral/repay/
//    liquidate, and added a nonReentrant guard as defense-in-depth.
// 3. Guardian is two-step transferable (nominate + accept), same reasoning
//    as ArcSwap v2 — a lost key shouldn't be a permanent dead end.
//
// Still true of this design (unchanged, documented for transparency): this
// remains a stablecoin-pegged-price assumption model with no price oracle.
// The pause added here is a mitigation, not a fix — a real oracle-based
// solvency check would be a stronger mainnet requirement.
contract ArcLending {
    IERC20 public immutable usdc;
    IERC20 public immutable eurc;

    uint256 constant LTV_BPS = 7500;
    uint256 constant LIQUIDATION_BPS = 8500;
    uint256 constant BASE_RATE_BPS = 200;
    uint256 constant SLOPE_BPS = 1800;
    uint256 constant BPS_DENOM = 10000;
    uint256 constant SECONDS_PER_YEAR = 365 days;

    uint256 public totalSupplied;
    uint256 public totalBorrowed;
    uint256 public lastAccrualTime;
    uint256 public borrowIndex = 1e18;

    mapping(address => uint256) public suppliedShares;
    uint256 public totalSupplyShares;

    mapping(address => uint256) public collateralBalance;
    mapping(address => uint256) public borrowedPrincipal;
    mapping(address => uint256) public borrowIndexSnapshot;

    address public guardian;
    address public pendingGuardian;
    bool public borrowingPaused;

    uint256 private locked; // reentrancy guard: 0 = unlocked, 1 = locked

    event Supplied(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event CollateralDeposited(address indexed user, uint256 amount);
    event CollateralWithdrawn(address indexed user, uint256 amount);
    event Borrowed(address indexed user, uint256 amount);
    event Repaid(address indexed user, uint256 amount);
    event Liquidated(address indexed borrower, address indexed liquidator, uint256 debtCovered, uint256 collateralSeized);
    event BorrowingPaused(address indexed by);
    event BorrowingUnpaused(address indexed by);
    event GuardianTransferStarted(address indexed currentGuardian, address indexed pendingGuardian);
    event GuardianTransferred(address indexed previousGuardian, address indexed newGuardian);

    modifier onlyGuardian() {
        require(msg.sender == guardian, "Not guardian");
        _;
    }

    modifier nonReentrant() {
        require(locked == 0, "Reentrancy blocked");
        locked = 1;
        _;
        locked = 0;
    }

    constructor(address _usdc, address _eurc) {
        usdc = IERC20(_usdc);
        eurc = IERC20(_eurc);
        lastAccrualTime = block.timestamp;
        guardian = msg.sender;
    }

    // ---------- Guardian: pause/unpause new borrowing only ----------

    function pauseBorrowing() external onlyGuardian {
        borrowingPaused = true;
        emit BorrowingPaused(msg.sender);
    }

    function unpauseBorrowing() external onlyGuardian {
        borrowingPaused = false;
        emit BorrowingUnpaused(msg.sender);
    }

    function transferGuardian(address newGuardian) external onlyGuardian {
        require(newGuardian != address(0), "Zero address");
        pendingGuardian = newGuardian;
        emit GuardianTransferStarted(guardian, newGuardian);
    }

    function acceptGuardian() external {
        require(msg.sender == pendingGuardian, "Not pending guardian");
        address previous = guardian;
        guardian = pendingGuardian;
        pendingGuardian = address(0);
        emit GuardianTransferred(previous, guardian);
    }

    function accrueInterest() public {
        if (block.timestamp == lastAccrualTime) return;
        uint256 elapsed = block.timestamp - lastAccrualTime;
        uint256 utilization = totalSupplied == 0 ? 0 : (totalBorrowed * BPS_DENOM) / totalSupplied;
        uint256 rateBps = BASE_RATE_BPS + (SLOPE_BPS * utilization) / BPS_DENOM;

        uint256 interestFactor = (rateBps * elapsed * 1e18) / (BPS_DENOM * SECONDS_PER_YEAR);
        borrowIndex += (borrowIndex * interestFactor) / 1e18;

        uint256 interestAccrued = (totalBorrowed * interestFactor) / 1e18;
        totalBorrowed += interestAccrued;
        totalSupplied += interestAccrued;

        lastAccrualTime = block.timestamp;
    }

    function currentAPR() external view returns (uint256 bps) {
        uint256 utilization = totalSupplied == 0 ? 0 : (totalBorrowed * BPS_DENOM) / totalSupplied;
        bps = BASE_RATE_BPS + (SLOPE_BPS * utilization) / BPS_DENOM;
    }

    // ---------- Supply side ----------

    function supply(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        accrueInterest();

        uint256 shares = totalSupplyShares == 0 ? amount : (amount * totalSupplyShares) / totalSupplied;

        suppliedShares[msg.sender] += shares;
        totalSupplyShares += shares;
        totalSupplied += amount;

        require(usdc.transferFrom(msg.sender, address(this), amount), "USDC transfer failed");

        emit Supplied(msg.sender, amount);
    }

    function withdraw(uint256 shareAmount) external nonReentrant {
        require(shareAmount > 0 && shareAmount <= suppliedShares[msg.sender], "Invalid shares");
        accrueInterest();

        uint256 amount = (shareAmount * totalSupplied) / totalSupplyShares;
        uint256 available = totalSupplied - totalBorrowed;
        require(amount <= available, "Insufficient available liquidity");

        suppliedShares[msg.sender] -= shareAmount;
        totalSupplyShares -= shareAmount;
        totalSupplied -= amount;

        require(usdc.transfer(msg.sender, amount), "USDC transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    function supplyBalance(address user) public view returns (uint256) {
        if (totalSupplyShares == 0) return 0;
        return (suppliedShares[user] * totalSupplied) / totalSupplyShares;
    }

    // ---------- Collateral & borrow side ----------

    function depositCollateral(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        collateralBalance[msg.sender] += amount;
        require(eurc.transferFrom(msg.sender, address(this), amount), "EURC transfer failed");
        emit CollateralDeposited(msg.sender, amount);
    }

    function withdrawCollateral(uint256 amount) external nonReentrant {
        accrueInterest();
        _syncBorrower(msg.sender);
        require(amount > 0 && amount <= collateralBalance[msg.sender], "Invalid amount");

        uint256 remainingCollateral = collateralBalance[msg.sender] - amount;
        uint256 debt = borrowedPrincipal[msg.sender];
        require(debt * BPS_DENOM <= remainingCollateral * LTV_BPS, "Would exceed LTV");

        collateralBalance[msg.sender] -= amount;
        require(eurc.transfer(msg.sender, amount), "EURC transfer failed");
        emit CollateralWithdrawn(msg.sender, amount);
    }

    function _syncBorrower(address user) internal {
        if (borrowIndexSnapshot[user] == 0) {
            borrowIndexSnapshot[user] = borrowIndex;
            return;
        }
        if (borrowedPrincipal[user] > 0) {
            uint256 accrued = (borrowedPrincipal[user] * borrowIndex) / borrowIndexSnapshot[user];
            borrowedPrincipal[user] = accrued;
        }
        borrowIndexSnapshot[user] = borrowIndex;
    }

    function debtOf(address user) public view returns (uint256) {
        if (borrowedPrincipal[user] == 0 || borrowIndexSnapshot[user] == 0) return borrowedPrincipal[user];
        return (borrowedPrincipal[user] * borrowIndex) / borrowIndexSnapshot[user];
    }

    function maxBorrowable(address user) public view returns (uint256) {
        uint256 capacity = (collateralBalance[user] * LTV_BPS) / BPS_DENOM;
        uint256 debt = debtOf(user);
        return capacity > debt ? capacity - debt : 0;
    }

    function healthFactor(address user) public view returns (uint256 bps) {
        uint256 debt = debtOf(user);
        if (debt == 0) return type(uint256).max;
        uint256 liqThreshold = (collateralBalance[user] * LIQUIDATION_BPS) / BPS_DENOM;
        return (liqThreshold * BPS_DENOM) / debt;
    }

    function borrow(uint256 amount) external nonReentrant {
        require(!borrowingPaused, "Borrowing is paused");
        require(amount > 0, "Amount must be > 0");
        accrueInterest();
        _syncBorrower(msg.sender);

        require(amount <= maxBorrowable(msg.sender), "Exceeds borrowing capacity");
        require(amount <= totalSupplied - totalBorrowed, "Insufficient pool liquidity");

        borrowedPrincipal[msg.sender] += amount;
        totalBorrowed += amount;

        require(usdc.transfer(msg.sender, amount), "USDC transfer failed");
        emit Borrowed(msg.sender, amount);
    }

    function repay(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        accrueInterest();
        _syncBorrower(msg.sender);

        uint256 debt = borrowedPrincipal[msg.sender];
        uint256 payment = amount > debt ? debt : amount;
        require(payment > 0, "No debt to repay");

        borrowedPrincipal[msg.sender] -= payment;
        totalBorrowed -= payment;

        require(usdc.transferFrom(msg.sender, address(this), payment), "USDC transfer failed");
        emit Repaid(msg.sender, payment);
    }

    // ---------- Liquidation ----------

    function liquidate(address borrower, uint256 repayAmount) external nonReentrant {
        accrueInterest();
        _syncBorrower(borrower);

        require(healthFactor(borrower) < BPS_DENOM, "Position is healthy");
        uint256 debt = borrowedPrincipal[borrower];
        uint256 actualRepay = repayAmount > debt ? debt : repayAmount;
        require(actualRepay > 0, "Nothing to liquidate");

        uint256 collateralSeized = (actualRepay * 10500) / BPS_DENOM;
        if (collateralSeized > collateralBalance[borrower]) {
            collateralSeized = collateralBalance[borrower];
        }

        borrowedPrincipal[borrower] -= actualRepay;
        totalBorrowed -= actualRepay;
        collateralBalance[borrower] -= collateralSeized;

        require(usdc.transferFrom(msg.sender, address(this), actualRepay), "USDC transfer failed");
        require(eurc.transfer(msg.sender, collateralSeized), "EURC transfer failed");
        emit Liquidated(borrower, msg.sender, actualRepay, collateralSeized);
    }

    // ---------- Views ----------

    function getMarketInfo() external view returns (uint256 _totalSupplied, uint256 _totalBorrowed, uint256 _availableLiquidity) {
        _totalSupplied = totalSupplied;
        _totalBorrowed = totalBorrowed;
        _availableLiquidity = totalSupplied > totalBorrowed ? totalSupplied - totalBorrowed : 0;
    }
}

contracts/ArcSwap.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// v2 changes from the original ArcSwap (audit findings addressed):
// 1. swapUsdcToEurc/swapEurcToUsdc now take a minAmountOut parameter — a
//    caller can no longer be silently rate-changed against between quoting
//    and execution.
// 2. Added pause()/unpause() — an emergency stop for swaps if a bug or
//    exploit is discovered, without needing to drain liquidity as the only
//    "emergency" tool.
// 3. withdrawLiquidity now emits a LiquidityWithdrawn event — on-chain
//    withdrawals by the owner are now publicly observable.
// 4. Added transferOwnership() with a two-step accept flow, so a lost/
//    compromised owner key isn't a permanent dead end and a typo'd address
//    can't accidentally become the new owner.
// 5. Added a nonReentrant guard on the swap functions as defense-in-depth.
//
// v5 changes from v2 (security review, second pass):
// 6. withdrawLiquidity now only accepts USDC or EURC — previously any
//    token address, so the owner could withdraw anything this contract
//    happened to hold.
// 7. setRate can now only move the rate by 10% per call — previously any
//    value > 0 was accepted in one shot, so a fat-finger or malicious
//    call could set an absurd rate before anyone noticed.
//
// Still true of this design (unchanged, documented for transparency): the
// exchange rate is owner-set, not oracle-derived. This is a fixed-rate demo
// pool, not a price-discovery AMM — pair this contract with real oracle
// pricing before any mainnet or real-funds use.
contract ArcSwap {
    address public owner;
    address public pendingOwner;
    IERC20 public immutable usdc;
    IERC20 public immutable eurc;

    uint256 public usdcToEurcRate;
    bool public paused;

    uint256 private locked; // reentrancy guard: 0 = unlocked, 1 = locked

    event Swapped(address indexed user, bool usdcToEurc, uint256 amountIn, uint256 amountOut);
    event RateUpdated(uint256 oldRate, uint256 newRate);
    event LiquidityAdded(address indexed provider, uint256 usdcAmount, uint256 eurcAmount);
    event LiquidityWithdrawn(address indexed owner, address indexed token, uint256 amount);
    event Paused(address indexed by);
    event Unpaused(address indexed by);
    event OwnershipTransferStarted(address indexed currentOwner, address indexed pendingOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Swaps are paused");
        _;
    }

    modifier nonReentrant() {
        require(locked == 0, "Reentrancy blocked");
        locked = 1;
        _;
        locked = 0;
    }

    constructor(address _usdc, address _eurc, uint256 _initialRate) {
        owner = msg.sender;
        usdc = IERC20(_usdc);
        eurc = IERC20(_eurc);
        usdcToEurcRate = _initialRate;
    }

    // v5 fix (security review): setRate previously accepted any value > 0 —
    // a single call (fat-finger or malicious) could set an absurd rate and
    // let anyone drain the pool at that price before it's noticed. A single
    // update can now move the rate by at most 10% — enough for the owner to
    // track real EUR/USD movement over time, not enough for one call to do
    // real damage. To move further, call setRate() again after the first
    // update lands.
    uint256 constant MAX_RATE_CHANGE_BPS = 1000; // 10%, in basis points (10000 = 100%)

    function setRate(uint256 newRate) external onlyOwner {
        require(newRate > 0, "Invalid rate");
        uint256 current = usdcToEurcRate;
        if (current > 0) {
            uint256 maxDelta = (current * MAX_RATE_CHANGE_BPS) / 10000;
            require(
                newRate >= current - maxDelta && newRate <= current + maxDelta,
                "Rate change exceeds 10% limit per call"
            );
        }
        emit RateUpdated(current, newRate);
        usdcToEurcRate = newRate;
    }

    function pause() external onlyOwner {
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused(msg.sender);
    }

    // Two-step ownership transfer: current owner nominates a successor, and
    // that successor must actively accept before control moves. This
    // prevents a single mistyped address from permanently locking the
    // contract out of anyone's control.
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Zero address");
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "Not pending owner");
        address previousOwner = owner;
        owner = pendingOwner;
        pendingOwner = address(0);
        emit OwnershipTransferred(previousOwner, owner);
    }

    function addLiquidity(uint256 usdcAmount, uint256 eurcAmount) external onlyOwner {
        if (usdcAmount > 0) {
            require(usdc.transferFrom(msg.sender, address(this), usdcAmount), "USDC transfer failed");
        }
        if (eurcAmount > 0) {
            require(eurc.transferFrom(msg.sender, address(this), eurcAmount), "EURC transfer failed");
        }
        emit LiquidityAdded(msg.sender, usdcAmount, eurcAmount);
    }

    // v5 fix (security review): withdrawLiquidity previously accepted ANY
    // token address — the owner could withdraw any ERC20 this contract
    // happened to hold, not just the two it's actually meant to custody.
    // Restricted to USDC/EURC only.
    function withdrawLiquidity(address token, uint256 amount) external onlyOwner {
        require(token == address(usdc) || token == address(eurc), "Can only withdraw USDC or EURC");
        require(IERC20(token).transfer(owner, amount), "Withdraw failed");
        emit LiquidityWithdrawn(owner, token, amount);
    }

    function swapUsdcToEurc(uint256 amountIn, uint256 minAmountOut) external whenNotPaused nonReentrant {
        require(amountIn > 0, "Amount must be > 0");
        uint256 amountOut = (amountIn * usdcToEurcRate) / 1e6;
        require(amountOut >= minAmountOut, "Slippage too high");
        require(eurc.balanceOf(address(this)) >= amountOut, "Insufficient EURC liquidity");

        require(usdc.transferFrom(msg.sender, address(this), amountIn), "USDC transfer failed");
        require(eurc.transfer(msg.sender, amountOut), "EURC transfer failed");

        emit Swapped(msg.sender, true, amountIn, amountOut);
    }

    function swapEurcToUsdc(uint256 amountIn, uint256 minAmountOut) external whenNotPaused nonReentrant {
        require(amountIn > 0, "Amount must be > 0");
        uint256 amountOut = (amountIn * 1e6) / usdcToEurcRate;
        require(amountOut >= minAmountOut, "Slippage too high");
        require(usdc.balanceOf(address(this)) >= amountOut, "Insufficient USDC liquidity");

        require(eurc.transferFrom(msg.sender, address(this), amountIn), "EURC transfer failed");
        require(usdc.transfer(msg.sender, amountOut), "USDC transfer failed");

        emit Swapped(msg.sender, false, amountIn, amountOut);
    }

    function getEurcOut(uint256 usdcIn) external view returns (uint256) {
        return (usdcIn * usdcToEurcRate) / 1e6;
    }

    function getUsdcOut(uint256 eurcIn) external view returns (uint256) {
        return (eurcIn * 1e6) / usdcToEurcRate;
    }

    function getLiquidity() external view returns (uint256 usdcBalance, uint256 eurcBalance) {
        return (usdc.balanceOf(address(this)), eurc.balanceOf(address(this)));
    }
}

contracts/ArcTokenFactoryV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

// ArcTokenFactoryV2 — token launch, learning from o1.exchange's production
// launchpad model, adapted honestly to FlowFi's actual architecture:
//
// 1. PERMANENT LIQUIDITY LOCK (adopted) — the old TokenFactory minted a bare
//    ERC-20 with no pool step at all. This version adds lockLaunchLiquidity():
//    once a pool exists for a launched token (created through the existing,
//    unchanged, owner-gated Pools flow — deliberately NOT touched here),
//    anyone can deposit the launch liquidity through this contract, and the
//    resulting LP shares are held by this contract forever — no withdraw
//    function is exposed anywhere, so the lock is structural, not a
//    separate burn step that could be forgotten.
//
//    Pool creation itself stays exactly as it is today (owner-only
//    createPool on ArcFactoryV2) — this contract does not attempt to call
//    it, avoiding the owner-gate conflict entirely. This means launching a
//    token and locking its liquidity is two on-chain steps, not one atomic
//    transaction, in exchange for not touching working, curated
//    infrastructure.
//
// 2. ANTI-SNIPE WINDOW (adopted, honestly scoped) — buyDuringLaunch()
//    enforces a per-wallet cap (2% of supply) for the first 20 seconds
//    after launch, for anyone buying through this contract. It cannot
//    (without changing ArcPool itself, which serves every pair on FlowFi,
//    not just launches) block a direct call to the pool's own swap() during
//    that window — a real, stated limitation, not hidden.
//
// 3. NET FEE SPLIT — not adopted. ArcPool's 0.3% fee accrues to liquidity
//    providers for every pair on FlowFi; splitting it three ways would mean
//    changing that shared contract's fee logic, a separate decision.
//
// 4. RESTRICTED PRICE UPDATER — not applicable. FlowFi's launched tokens
//    price purely by the AMM; there is no admin-set price for this role to
//    restrict.
//
// Token order safety: ArcPool exposes tokenA()/tokenB() as public immutable
// state — this contract always reads that order live rather than assuming
// which side the owner passed to createPool.

interface IArcPool {
    function addLiquidity(uint256 amountADesired, uint256 amountBDesired, uint256 amountAMin, uint256 amountBMin, uint256 deadline) external returns (uint256 mintedShares);
    function swap(bool aToB, uint256 amountIn, uint256 minAmountOut, uint256 deadline) external returns (uint256 amountOut);
    function tokenA() external view returns (address);
    function tokenB() external view returns (address);
    function totalShares() external view returns (uint256);
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

contract LaunchedToken {
    string public name;
    string public symbol;
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    address public immutable creator;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory _name, string memory _symbol, uint256 _supply, address _creator) {
        name = _name;
        symbol = _symbol;
        totalSupply = _supply;
        creator = _creator;
        balanceOf[_creator] = _supply; // minted straight to the creator, who then approves the factory for the locking step
        emit Transfer(address(0), _creator, _supply);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        require(allowed >= amount, "Allowance exceeded");
        if (allowed != type(uint256).max) allowance[from][msg.sender] = allowed - amount;
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(balanceOf[from] >= amount, "Insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
    }
}

contract ArcTokenFactoryV2 {
    address public immutable usdc;
    uint256 public constant ANTI_SNIPE_WINDOW = 20 seconds;
    uint256 public constant ANTI_SNIPE_MAX_BUY_BPS = 200; // 2% of total supply, per wallet, during the window

    address[] public allTokens;
    mapping(address => uint256) public tokenSupply;
    mapping(address => uint256) public launchedAt;
    mapping(address => address) public tokenPool; // set once, by lockLaunchLiquidity
    mapping(address => mapping(address => uint256)) public boughtDuringSnipeWindow;

    event TokenLaunched(address indexed token, address indexed creator, uint256 supply);
    event LiquidityLocked(address indexed token, address indexed pool, uint256 tokenAmount, uint256 usdcAmount);

    constructor(address _usdc) {
        usdc = _usdc;
    }

    function launchToken(string calldata name, string calldata symbol, uint256 supply) external returns (address token) {
        require(supply > 0, "Supply must be > 0");
        LaunchedToken newToken = new LaunchedToken(name, symbol, supply, msg.sender);
        token = address(newToken);
        tokenSupply[token] = supply;
        launchedAt[token] = block.timestamp;
        allTokens.push(token);
        emit TokenLaunched(token, msg.sender, supply);
    }

    // Call after a pool already exists for `token` (created through the
    // normal, unchanged, owner-gated Pools flow). Caller must first approve
    // this contract for both `tokenAmount` of `token` and `usdcAmount` of
    // USDC. This must be the pool's first-ever deposit (totalShares == 0 in
    // ArcPool), which is why amountAMin/amountBMin = 0 is safe — no
    // ratio-matching or partial-fill risk exists on a first deposit. Can
    // only be called once per token.
    function lockLaunchLiquidity(address token, address pool, uint256 tokenAmount, uint256 usdcAmount, uint256 deadline) external {
        require(tokenSupply[token] > 0, "Not a token launched here");
        require(tokenPool[token] == address(0), "Already locked for this token");
        require(block.timestamp <= deadline, "Transaction expired");

        address a = IArcPool(pool).tokenA();
        address b = IArcPool(pool).tokenB();
        require((a == token && b == usdc) || (a == usdc && b == token), "Pool is not for this token/USDC pair");
        require(IArcPool(pool).totalShares() == 0, "Pool already has liquidity, launch-lock path is first-deposit only");
        tokenPool[token] = pool;

        IERC20(token).transferFrom(msg.sender, address(this), tokenAmount);
        IERC20(usdc).transferFrom(msg.sender, address(this), usdcAmount);
        IERC20(token).approve(pool, tokenAmount);
        IERC20(usdc).approve(pool, usdcAmount);

        if (a == token) {
            IArcPool(pool).addLiquidity(tokenAmount, usdcAmount, 0, 0, deadline);
        } else {
            IArcPool(pool).addLiquidity(usdcAmount, tokenAmount, 0, 0, deadline);
        }
        // Resulting LP shares are recorded under this contract's address
        // inside ArcPool's own storage. No function anywhere in this
        // contract ever calls removeLiquidity — the lock is permanent by
        // omission, not by a revocable flag.

        emit LiquidityLocked(token, pool, tokenAmount, usdcAmount);
    }

    // Anti-snipe buy path. Honest limitation stated at the top of this file:
    // this caps purchases made THROUGH this function, not direct calls to
    // the pool's own swap().
    function buyDuringLaunch(address token, uint256 usdcIn, uint256 minTokenOut, uint256 deadline) external returns (uint256 tokenOut) {
        address pool = tokenPool[token];
        require(pool != address(0), "Liquidity not locked yet for this token");
        require(block.timestamp <= deadline, "Transaction expired");

        bool tokenIsA = IArcPool(pool).tokenA() == token;

        IERC20(usdc).transferFrom(msg.sender, address(this), usdcIn);
        IERC20(usdc).approve(pool, usdcIn);
        // Buying `token` with USDC: if token is tokenA, USDC is tokenB, so
        // the swap direction (A to B) is false — USDC (B) moves in, token
        // (A) moves out.
        tokenOut = IArcPool(pool).swap(!tokenIsA, usdcIn, minTokenOut, deadline);

        bool inSnipeWindow = block.timestamp <= launchedAt[token] + ANTI_SNIPE_WINDOW;
        if (inSnipeWindow) {
            uint256 cap = (tokenSupply[token] * ANTI_SNIPE_MAX_BUY_BPS) / 10000;
            uint256 newTotal = boughtDuringSnipeWindow[token][msg.sender] + tokenOut;
            require(newTotal <= cap, "Anti-snipe cap exceeded for this wallet");
            boughtDuringSnipeWindow[token][msg.sender] = newTotal;
        }

        IERC20(token).transfer(msg.sender, tokenOut);
    }

    function allTokensLength() external view returns (uint256) {
        return allTokens.length;
    }
}

contracts/core/GiwaCLDeployer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./GiwaCLPool.sol";
import "../interfaces/IGiwaPoolDeployer.sol";

/// @title GiwaCLDeployer
/// @notice Dedicated deployer contract for Concentrated Liquidity Pools (CLAMM)
contract GiwaCLDeployer is IGiwaCLDeployer {
    address public factory;
    address public owner;

    event FactorySet(address indexed factory);

    constructor() {
        owner = msg.sender;
    }

    function setFactory(address _factory) external {
        require(msg.sender == owner, "GiwaCLDeployer: FORBIDDEN");
        require(factory == address(0), "GiwaCLDeployer: ALREADY_SET");
        require(_factory != address(0), "GiwaCLDeployer: ZERO_ADDRESS");
        factory = _factory;
        emit FactorySet(_factory);
    }

    function deployCLPool(
        bytes32 salt,
        address token0,
        address token1,
        uint24 fee,
        int24 tickSpacing,
        address feeVault
    ) external override returns (address pool) {
        require(msg.sender == factory, "GiwaCLDeployer: FORBIDDEN");
        pool = address(new GiwaCLPool{salt: salt}(token0, token1, fee, tickSpacing, feeVault));
    }
}

contracts/core/GiwaCLPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../interfaces/IGiwaCLPool.sol";
import "../interfaces/IGiwaPoolFactory.sol";
import "../libraries/FullMath.sol";
import "../libraries/TickMath.sol";
import "../libraries/SqrtPriceMath.sol";
import "../libraries/SwapMath.sol";
import "../libraries/TickBitmap.sol";
import "../libraries/SafeCast.sol";
import "../libraries/TransientReentrancyGuard.sol";

interface IERC20Minimal {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IGiwaSwapCallback {
    function giwaSwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) external;
}

interface IGiwaMintCallback {
    function giwaMintCallback(uint256 amount0Owed, uint256 amount1Owed, bytes calldata data) external;
}

interface IGiwaFlashCallback {
    function giwaFlashCallback(uint256 fee0, uint256 fee1, bytes calldata data) external;
}

/// @title GiwaCLPool
/// @notice Production Concentrated Liquidity AMM Pool on Giwa Chain with Cancun transient storage reentrancy protection.
contract GiwaCLPool is IGiwaCLPool, TransientReentrancyGuard {
    using SafeCast for uint256;
    using SafeCast for int256;
    using TickBitmap for mapping(int16 => uint256);

    address public override immutable factory;
    address public override immutable token0;
    address public override immutable token1;
    uint24 public override immutable fee;
    int24 public override immutable tickSpacing;
    uint128 public override immutable maxLiquidityPerTick;
    address public immutable feeVault;

    struct PositionInfo {
        uint128 liquidity;
        uint256 feeGrowthInside0LastX128;
        uint256 feeGrowthInside1LastX128;
        uint128 tokensOwed0;
        uint128 tokensOwed1;
    }

    struct TickInfo {
        uint128 liquidityGross;
        int128 liquidityNet;
        uint256 feeGrowthOutside0X128;
        uint256 feeGrowthOutside1X128;
        bool initialized;
    }

    Slot0 public override slot0;
    uint128 public liquidity;
    uint256 public feeGrowthGlobal0X128;
    uint256 public feeGrowthGlobal1X128;

    mapping(int24 => TickInfo) public ticks;
    mapping(int16 => uint256) public tickBitmap;
    mapping(bytes32 => PositionInfo) public positions;

    constructor(
        address _token0,
        address _token1,
        uint24 _fee,
        int24 _tickSpacing,
        address _feeVault
    ) {
        factory = msg.sender;
        token0 = _token0;
        token1 = _token1;
        fee = _fee;
        tickSpacing = _tickSpacing;
        feeVault = _feeVault;
        maxLiquidityPerTick = type(uint128).max / uint128(uint24((TickMath.MAX_TICK - TickMath.MIN_TICK) / _tickSpacing + 1));
    }

    function initialize(uint160 sqrtPriceX96) external override {
        require(slot0.sqrtPriceX96 == 0, "CLPool: ALREADY_INITIALIZED");
        int24 tick = TickMath.getTickAtSqrtRatio(sqrtPriceX96);
        slot0 = Slot0({
            sqrtPriceX96: sqrtPriceX96,
            tick: tick,
            observationIndex: 0,
            observationCardinality: 1,
            observationCardinalityNext: 1,
            feeProtocol: 0,
            unlocked: true
        });
        emit Initialize(sqrtPriceX96, tick);
    }

    function _positionKey(address owner, int24 tickLower, int24 tickUpper) private pure returns (bytes32) {
        return keccak256(abi.encodePacked(owner, tickLower, tickUpper));
    }

    function mint(
        address recipient,
        int24 tickLower,
        int24 tickUpper,
        uint128 amount,
        bytes calldata data
    ) external override nonReentrant returns (uint256 amount0, uint256 amount1) {
        require(tickLower < tickUpper && tickLower >= TickMath.MIN_TICK && tickUpper <= TickMath.MAX_TICK, "CLPool: INVALID_TICKS");
        require(tickLower % tickSpacing == 0 && tickUpper % tickSpacing == 0, "CLPool: TICK_SPACING");
        require(amount > 0, "CLPool: AMOUNT_ZERO");

        Slot0 memory _slot0 = slot0;
        require(_slot0.sqrtPriceX96 > 0, "CLPool: NOT_INITIALIZED");

        if (_slot0.tick < tickLower) {
            amount0 = SqrtPriceMath.getAmount0Delta(
                TickMath.getSqrtRatioAtTick(tickLower),
                TickMath.getSqrtRatioAtTick(tickUpper),
                amount,
                true
            );
        } else if (_slot0.tick < tickUpper) {
            amount0 = SqrtPriceMath.getAmount0Delta(
                _slot0.sqrtPriceX96,
                TickMath.getSqrtRatioAtTick(tickUpper),
                amount,
                true
            );
            amount1 = SqrtPriceMath.getAmount1Delta(
                TickMath.getSqrtRatioAtTick(tickLower),
                _slot0.sqrtPriceX96,
                amount,
                true
            );
            liquidity += amount;
        } else {
            amount1 = SqrtPriceMath.getAmount1Delta(
                TickMath.getSqrtRatioAtTick(tickLower),
                TickMath.getSqrtRatioAtTick(tickUpper),
                amount,
                true
            );
        }

        // Update position info
        bytes32 posKey = _positionKey(recipient, tickLower, tickUpper);
        positions[posKey].liquidity += amount;

        // Flip ticks in bitmap if new
        TickInfo storage tickInfoLower = ticks[tickLower];
        if (tickInfoLower.liquidityGross == 0) {
            tickBitmap.flipTick(tickLower, tickSpacing);
            tickInfoLower.initialized = true;
        }
        tickInfoLower.liquidityGross += amount;
        tickInfoLower.liquidityNet += int128(int256(uint256(amount)));

        TickInfo storage tickInfoUpper = ticks[tickUpper];
        if (tickInfoUpper.liquidityGross == 0) {
            tickBitmap.flipTick(tickUpper, tickSpacing);
            tickInfoUpper.initialized = true;
        }
        tickInfoUpper.liquidityGross += amount;
        tickInfoUpper.liquidityNet -= int128(int256(uint256(amount)));

        uint256 balance0Before = IERC20Minimal(token0).balanceOf(address(this));
        uint256 balance1Before = IERC20Minimal(token1).balanceOf(address(this));

        if (data.length > 0) {
            IGiwaMintCallback(msg.sender).giwaMintCallback(amount0, amount1, data);
        } else {
            if (amount0 > 0) _safeTransferFrom(token0, msg.sender, address(this), amount0);
            if (amount1 > 0) _safeTransferFrom(token1, msg.sender, address(this), amount1);
        }

        require(balance0Before + amount0 <= IERC20Minimal(token0).balanceOf(address(this)), "CLPool: MINT_TOKEN0");
        require(balance1Before + amount1 <= IERC20Minimal(token1).balanceOf(address(this)), "CLPool: MINT_TOKEN1");

        emit Mint(msg.sender, recipient, tickLower, tickUpper, amount, amount0, amount1);
    }

    function burn(
        int24 tickLower,
        int24 tickUpper,
        uint128 amount
    ) external override nonReentrant returns (uint256 amount0, uint256 amount1) {
        bytes32 posKey = _positionKey(msg.sender, tickLower, tickUpper);
        PositionInfo storage position = positions[posKey];
        require(position.liquidity >= amount, "CLPool: INSUFFICIENT_POSITION");

        Slot0 memory _slot0 = slot0;

        if (_slot0.tick < tickLower) {
            amount0 = SqrtPriceMath.getAmount0Delta(
                TickMath.getSqrtRatioAtTick(tickLower),
                TickMath.getSqrtRatioAtTick(tickUpper),
                amount,
                false
            );
        } else if (_slot0.tick < tickUpper) {
            amount0 = SqrtPriceMath.getAmount0Delta(
                _slot0.sqrtPriceX96,
                TickMath.getSqrtRatioAtTick(tickUpper),
                amount,
                false
            );
            amount1 = SqrtPriceMath.getAmount1Delta(
                TickMath.getSqrtRatioAtTick(tickLower),
                _slot0.sqrtPriceX96,
                amount,
                false
            );
            liquidity -= amount;
        } else {
            amount1 = SqrtPriceMath.getAmount1Delta(
                TickMath.getSqrtRatioAtTick(tickLower),
                TickMath.getSqrtRatioAtTick(tickUpper),
                amount,
                false
            );
        }

        position.liquidity -= amount;
        position.tokensOwed0 += uint128(amount0);
        position.tokensOwed1 += uint128(amount1);

        // Synchronize lower and upper ticks
        TickInfo storage tickInfoLower = ticks[tickLower];
        tickInfoLower.liquidityGross -= amount;
        tickInfoLower.liquidityNet -= int128(int256(uint256(amount)));
        if (tickInfoLower.liquidityGross == 0) {
            tickBitmap.flipTick(tickLower, tickSpacing);
            tickInfoLower.initialized = false;
        }

        TickInfo storage tickInfoUpper = ticks[tickUpper];
        tickInfoUpper.liquidityGross -= amount;
        tickInfoUpper.liquidityNet += int128(int256(uint256(amount)));
        if (tickInfoUpper.liquidityGross == 0) {
            tickBitmap.flipTick(tickUpper, tickSpacing);
            tickInfoUpper.initialized = false;
        }

        emit Burn(msg.sender, tickLower, tickUpper, amount, amount0, amount1);
    }

    function collect(
        address recipient,
        int24 tickLower,
        int24 tickUpper,
        uint128 amount0Requested,
        uint128 amount1Requested
    ) external override nonReentrant returns (uint128 amount0, uint128 amount1) {
        bytes32 posKey = _positionKey(msg.sender, tickLower, tickUpper);
        PositionInfo storage position = positions[posKey];

        amount0 = amount0Requested > position.tokensOwed0 ? position.tokensOwed0 : amount0Requested;
        amount1 = amount1Requested > position.tokensOwed1 ? position.tokensOwed1 : amount1Requested;

        if (amount0 > 0) {
            position.tokensOwed0 -= amount0;
            _safeTransfer(token0, recipient, amount0);
        }
        if (amount1 > 0) {
            position.tokensOwed1 -= amount1;
            _safeTransfer(token1, recipient, amount1);
        }

        emit Collect(msg.sender, recipient, tickLower, tickUpper, amount0, amount1);
    }

    struct SwapStepState {
        uint160 sqrtPriceStartX96;
        int24 tickNext;
        bool initialized;
        uint160 sqrtPriceNextX96;
        uint256 amountIn;
        uint256 amountOut;
        uint256 feeAmount;
    }

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external override nonReentrant returns (int256 amount0, int256 amount1) {
        require(amountSpecified != 0, "CLPool: AMOUNT_ZERO");
        Slot0 memory _slot0 = slot0;
        require(_slot0.sqrtPriceX96 > 0, "CLPool: NOT_INITIALIZED");

        if (zeroForOne) {
            require(sqrtPriceLimitX96 < _slot0.sqrtPriceX96 && sqrtPriceLimitX96 > TickMath.MIN_SQRT_RATIO, "CLPool: RATIO_LIMIT");
        } else {
            require(sqrtPriceLimitX96 > _slot0.sqrtPriceX96 && sqrtPriceLimitX96 < TickMath.MAX_SQRT_RATIO, "CLPool: RATIO_LIMIT");
        }

        bool exactInput = amountSpecified > 0;
        int256 amountSpecifiedRemaining = amountSpecified;
        int256 amountCalculated = 0;
        uint160 currentSqrtPriceX96 = _slot0.sqrtPriceX96;
        int24 currentTick = _slot0.tick;
        uint128 currentLiquidity = liquidity;

        while (amountSpecifiedRemaining != 0 && currentSqrtPriceX96 != sqrtPriceLimitX96) {
            SwapStepState memory step;
            step.sqrtPriceStartX96 = currentSqrtPriceX96;

            (step.tickNext, step.initialized) = tickBitmap.nextInitializedTickWithinOneWord(
                currentTick,
                tickSpacing,
                zeroForOne
            );

            if (step.tickNext < TickMath.MIN_TICK) step.tickNext = TickMath.MIN_TICK;
            else if (step.tickNext > TickMath.MAX_TICK) step.tickNext = TickMath.MAX_TICK;

            step.sqrtPriceNextX96 = TickMath.getSqrtRatioAtTick(step.tickNext);

            (currentSqrtPriceX96, step.amountIn, step.amountOut, step.feeAmount) = SwapMath.computeSwapStep(
                currentSqrtPriceX96,
                (zeroForOne ? step.sqrtPriceNextX96 < sqrtPriceLimitX96 : step.sqrtPriceNextX96 > sqrtPriceLimitX96)
                    ? sqrtPriceLimitX96
                    : step.sqrtPriceNextX96,
                currentLiquidity,
                amountSpecifiedRemaining,
                fee
            );

            if (exactInput) {
                amountSpecifiedRemaining -= int256(step.amountIn + step.feeAmount);
                amountCalculated -= int256(step.amountOut);
            } else {
                amountSpecifiedRemaining += int256(step.amountOut);
                amountCalculated += int256(step.amountIn + step.feeAmount);
            }

            if (currentSqrtPriceX96 == step.sqrtPriceNextX96) {
                if (step.initialized) {
                    int128 liquidityNet = ticks[step.tickNext].liquidityNet;
                    if (zeroForOne) liquidityNet = -liquidityNet;
                    currentLiquidity = liquidityNet < 0
                        ? currentLiquidity - uint128(-int128(liquidityNet))
                        : currentLiquidity + uint128(liquidityNet);
                }
                currentTick = zeroForOne ? step.tickNext - 1 : step.tickNext;
            } else if (currentSqrtPriceX96 != step.sqrtPriceStartX96) {
                currentTick = TickMath.getTickAtSqrtRatio(currentSqrtPriceX96);
            }
        }

        if (currentTick != _slot0.tick) {
            _slot0.sqrtPriceX96 = currentSqrtPriceX96;
            _slot0.tick = currentTick;
            slot0 = _slot0;
        } else if (currentSqrtPriceX96 != _slot0.sqrtPriceX96) {
            _slot0.sqrtPriceX96 = currentSqrtPriceX96;
            slot0 = _slot0;
        }

        if (liquidity != currentLiquidity) liquidity = currentLiquidity;

        (amount0, amount1) = zeroForOne == exactInput
            ? (amountSpecified - amountSpecifiedRemaining, amountCalculated)
            : (amountCalculated, amountSpecified - amountSpecifiedRemaining);

        if (zeroForOne) {
            if (amount1 < 0) _safeTransfer(token1, recipient, uint256(-amount1));
            uint256 balance0Before = IERC20Minimal(token0).balanceOf(address(this));
            if (data.length > 0) {
                IGiwaSwapCallback(msg.sender).giwaSwapCallback(amount0, amount1, data);
            } else {
                _safeTransferFrom(token0, msg.sender, address(this), uint256(amount0));
            }
            require(balance0Before + uint256(amount0) <= IERC20Minimal(token0).balanceOf(address(this)), "CLPool: SWAP_TOKEN0");
        } else {
            if (amount0 < 0) _safeTransfer(token0, recipient, uint256(-amount0));
            uint256 balance1Before = IERC20Minimal(token1).balanceOf(address(this));
            if (data.length > 0) {
                IGiwaSwapCallback(msg.sender).giwaSwapCallback(amount0, amount1, data);
            } else {
                _safeTransferFrom(token1, msg.sender, address(this), uint256(amount1));
            }
            require(balance1Before + uint256(amount1) <= IERC20Minimal(token1).balanceOf(address(this)), "CLPool: SWAP_TOKEN1");
        }

        emit Swap(msg.sender, recipient, amount0, amount1, currentSqrtPriceX96, currentLiquidity, currentTick);
    }

    function flash(
        address recipient,
        uint256 amount0,
        uint256 amount1,
        bytes calldata data
    ) external override nonReentrant {
        uint256 fee0 = FullMath.mulDivRoundingUp(amount0, fee, 1e6);
        uint256 fee1 = FullMath.mulDivRoundingUp(amount1, fee, 1e6);

        uint256 balance0Before = IERC20Minimal(token0).balanceOf(address(this));
        uint256 balance1Before = IERC20Minimal(token1).balanceOf(address(this));

        if (amount0 > 0) _safeTransfer(token0, recipient, amount0);
        if (amount1 > 0) _safeTransfer(token1, recipient, amount1);

        IGiwaFlashCallback(msg.sender).giwaFlashCallback(fee0, fee1, data);

        require(balance0Before + fee0 <= IERC20Minimal(token0).balanceOf(address(this)), "CLPool: FLASH_TOKEN0");
        require(balance1Before + fee1 <= IERC20Minimal(token1).balanceOf(address(this)), "CLPool: FLASH_TOKEN1");

        emit Flash(recipient, msg.sender, amount0, amount1, fee0, fee1);
    }

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20Minimal.transfer.selector, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "CLPool: TRANSFER_FAILED");
    }

    function _safeTransferFrom(address token, address from, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20Minimal.transferFrom.selector, from, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "CLPool: TRANSFER_FROM_FAILED");
    }
}

contracts/core/GiwaPoolFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IGiwaPoolFactory.sol";
import "../interfaces/IGiwaPoolDeployer.sol";

/// @title GiwaPoolFactory
/// @notice Core Factory contract for deploying Concentrated Liquidity (CLAMM) and Stableswap pools on Giwa Chain.
contract GiwaPoolFactory is IGiwaPoolFactory {
    address public override owner;
    address public override feeVault;
    address public clDeployer;
    address public stableDeployer;

    mapping(uint24 => int24) public override feeAmountTickSpacing;
    mapping(address => mapping(address => mapping(uint24 => mapping(bool => address)))) public getPoolMapping;
    address[] public override allPools;

    modifier onlyOwner() {
        require(msg.sender == owner, "GiwaPoolFactory: FORBIDDEN");
        _;
    }

    constructor(address _feeVault, address _clDeployer, address _stableDeployer) {
        require(_feeVault != address(0), "GiwaPoolFactory: ZERO_ADDRESS");
        require(_clDeployer != address(0), "GiwaPoolFactory: ZERO_ADDRESS");
        require(_stableDeployer != address(0), "GiwaPoolFactory: ZERO_ADDRESS");
        owner = msg.sender;
        feeVault = _feeVault;
        clDeployer = _clDeployer;
        stableDeployer = _stableDeployer;

        // Initialize standard fee tiers and tick spacings (Uniswap v3 / Giwa CLAMM standard)
        _enableFeeAmount(100, 1);    // 0.01% - Tick spacing 1 (Pegged/Stable pairs)
        _enableFeeAmount(500, 10);   // 0.05% - Tick spacing 10 (Correlated assets)
        _enableFeeAmount(3000, 60);  // 0.30% - Tick spacing 60 (Standard volatile pairs)
        _enableFeeAmount(10000, 200);// 1.00% - Tick spacing 200 (Exotic pairs)
    }

    function allPoolsLength() external view override returns (uint256) {
        return allPools.length;
    }

    function getPool(
        address tokenA,
        address tokenB,
        uint24 fee,
        bool isStable
    ) external view override returns (address) {
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        return getPoolMapping[token0][token1][fee][isStable];
    }

    function createPool(
        address tokenA,
        address tokenB,
        uint24 fee,
        bool isStable
    ) external override returns (address pool) {
        require(tokenA != tokenB, "GiwaPoolFactory: IDENTICAL_ADDRESSES");
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), "GiwaPoolFactory: ZERO_ADDRESS");
        require(getPoolMapping[token0][token1][fee][isStable] == address(0), "GiwaPoolFactory: POOL_EXISTS");

        int24 tickSpacing = feeAmountTickSpacing[fee];
        require(tickSpacing != 0, "GiwaPoolFactory: FEE_NOT_ENABLED");

        bytes32 salt = keccak256(abi.encodePacked(token0, token1, fee, isStable));

        if (isStable) {
            pool = IGiwaStableDeployer(stableDeployer).deployStablePool(salt, token0, token1, fee, feeVault);
        } else {
            pool = IGiwaCLDeployer(clDeployer).deployCLPool(salt, token0, token1, fee, tickSpacing, feeVault);
        }

        getPoolMapping[token0][token1][fee][isStable] = pool;
        getPoolMapping[token1][token0][fee][isStable] = pool;
        allPools.push(pool);

        emit PoolCreated(token0, token1, fee, tickSpacing, isStable, pool);
    }

    function enableFeeAmount(uint24 fee, int24 tickSpacing) external override onlyOwner {
        _enableFeeAmount(fee, tickSpacing);
    }

    function _enableFeeAmount(uint24 fee, int24 tickSpacing) private {
        require(fee < 1000000, "GiwaPoolFactory: FEE_TOO_HIGH");
        require(tickSpacing > 0 && tickSpacing <= 16384, "GiwaPoolFactory: INVALID_TICK_SPACING");
        require(feeAmountTickSpacing[fee] == 0, "GiwaPoolFactory: FEE_ALREADY_ENABLED");

        feeAmountTickSpacing[fee] = tickSpacing;
        emit FeeAmountEnabled(fee, tickSpacing);
    }

    function setFeeVault(address _feeVault) external override onlyOwner {
        require(_feeVault != address(0), "GiwaPoolFactory: ZERO_ADDRESS");
        feeVault = _feeVault;
        emit FeeVaultSet(_feeVault);
    }

    function setOwner(address _newOwner) external override onlyOwner {
        require(_newOwner != address(0), "GiwaPoolFactory: ZERO_ADDRESS");
        emit OwnerChanged(owner, _newOwner);
        owner = _newOwner;
    }
}

