// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IGiwaFactory.sol";
import "./GiwaPool.sol";

/// @title GiwaFactory
/// @notice Deploys and catalogs Giwa DEX liquidity pools with customizable fee tiers.
contract GiwaFactory is IGiwaFactory {
    address public owner;
    address public feeVault;

    mapping(address => mapping(address => mapping(bool => address))) public getPool;
    address[] public allPools;
    mapping(uint256 => bool) public isFeeTierEnabled;

    modifier onlyOwner() {
        require(msg.sender == owner, "GiwaFactory: FORBIDDEN");
        _;
    }

    constructor(address _feeVault) {
        owner = msg.sender;
        feeVault = _feeVault;

        // Initialize standard fee tiers (in basis points)
        isFeeTierEnabled[1] = true;   // 0.01% - Pegged Stablecoins
        isFeeTierEnabled[5] = true;   // 0.05% - Correlated Assets
        isFeeTierEnabled[30] = true;  // 0.30% - Standard Volatile Pairs
        isFeeTierEnabled[100] = true; // 1.00% - Exotic / Long-tail Tokens
    }

    function allPoolsLength() external view returns (uint256) {
        return allPools.length;
    }

    function createPool(
        address tokenA,
        address tokenB,
        bool isStable,
        uint256 feeBps
    ) external returns (address pool) {
        require(tokenA != tokenB, "GiwaFactory: IDENTICAL_ADDRESSES");
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), "GiwaFactory: ZERO_ADDRESS");
        require(getPool[token0][token1][isStable] == address(0), "GiwaFactory: POOL_EXISTS");
        require(isFeeTierEnabled[feeBps], "GiwaFactory: FEE_TIER_NOT_ENABLED");

        bytes32 salt = keccak256(abi.encodePacked(token0, token1, isStable, feeBps));
        GiwaPool newPool = new GiwaPool{salt: salt}(token0, token1, isStable, feeBps);
        pool = address(newPool);

        getPool[token0][token1][isStable] = pool;
        getPool[token1][token0][isStable] = pool;
        allPools.push(pool);

        emit PoolCreated(token0, token1, isStable, feeBps, pool, allPools.length);
    }

    function setFeeVault(address newFeeVault) external onlyOwner {
        require(newFeeVault != address(0), "GiwaFactory: ZERO_ADDRESS");
        feeVault = newFeeVault;
        emit FeeVaultUpdated(newFeeVault);
    }

    function enableFeeTier(uint256 feeBps) external onlyOwner {
        require(feeBps > 0 && feeBps <= 1000, "GiwaFactory: INVALID_FEE"); // Max 10%
        isFeeTierEnabled[feeBps] = true;
        emit FeeTierSet(feeBps, true);
    }

    function setOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "GiwaFactory: ZERO_ADDRESS");
        owner = newOwner;
    }
}

contracts/GiwaPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IGiwaPool.sol";
import "./interfaces/IGiwaFactory.sol";

interface IERC20Minimal {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function decimals() external view returns (uint8);
}

/// @title GiwaPool
/// @notice High performance AMM Liquidity Pool engineered for Giwa Chain's 200ms Flashblocks.
/// @dev Supports both standard constant-product (xy=k) and stableswap curves with LP token minting.
contract GiwaPool is IGiwaPool {
    string public name;
    string public symbol;
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    address public immutable factory;
    address public immutable token0;
    address public immutable token1;
    bool public immutable isStable;
    uint256 public immutable feeBps; // Fee in basis points (e.g. 30 = 0.30%, 1 = 0.01%)

    uint112 private reserve0;
    uint112 private reserve1;
    uint32 private blockTimestampLast;

    uint256 private unlocked = 1;
    modifier nonReentrant() {
        require(unlocked == 1, "GiwaPool: LOCKED");
        unlocked = 0;
        _;
        unlocked = 1;
    }

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(
        address _token0,
        address _token1,
        bool _isStable,
        uint256 _feeBps
    ) {
        factory = msg.sender;
        token0 = _token0;
        token1 = _token1;
        isStable = _isStable;
        feeBps = _feeBps;

        name = string(abi.encodePacked("GIWA LP - ", _isStable ? "Stable" : "Volatile"));
        symbol = _isStable ? "gLP-s" : "gLP-v";
    }

    function _mintLP(address to, uint256 amount) internal {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function _burnLP(address from, uint256 amount) internal {
        balanceOf[from] -= amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address recipient, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "GiwaPool: INSUFFICIENT_BALANCE");
        balanceOf[msg.sender] -= amount;
        balanceOf[recipient] += amount;
        emit Transfer(msg.sender, recipient, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        uint256 currentAllowance = allowance[sender][msg.sender];
        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= amount, "GiwaPool: INSUFFICIENT_ALLOWANCE");
            allowance[sender][msg.sender] = currentAllowance - amount;
        }
        require(balanceOf[sender] >= amount, "GiwaPool: INSUFFICIENT_BALANCE");
        balanceOf[sender] -= amount;
        balanceOf[recipient] += amount;
        emit Transfer(sender, recipient, amount);
        return true;
    }

    function getReserves() external view returns (uint112 _reserve0, uint112 _reserve1, uint32 _blockTimestampLast) {
        _reserve0 = reserve0;
        _reserve1 = reserve1;
        _blockTimestampLast = blockTimestampLast;
    }

    function _update(uint256 balance0, uint256 balance1) private {
        require(balance0 <= type(uint112).max && balance1 <= type(uint112).max, "GiwaPool: OVERFLOW");
        reserve0 = uint112(balance0);
        reserve1 = uint112(balance1);
        blockTimestampLast = uint32(block.timestamp);
        emit Sync(reserve0, reserve1);
    }

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20Minimal.transfer.selector, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "GiwaPool: TRANSFER_FAILED");
    }

    function getAmountOut(uint256 amountIn, address tokenIn) public view returns (uint256 amountOut) {
        require(amountIn > 0, "GiwaPool: INSUFFICIENT_INPUT_AMOUNT");
        require(tokenIn == token0 || tokenIn == token1, "GiwaPool: INVALID_TOKEN");

        (uint256 reserveIn, uint256 reserveOut) = tokenIn == token0
            ? (uint256(reserve0), uint256(reserve1))
            : (uint256(reserve1), uint256(reserve0));

        require(reserveIn > 0 && reserveOut > 0, "GiwaPool: INSUFFICIENT_LIQUIDITY");

        uint256 feeMultiplier = 10000 - feeBps;
        uint256 amountInWithFee = amountIn * feeMultiplier;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = (reserveIn * 10000) + amountInWithFee;
        amountOut = numerator / denominator;
    }

    function mint(address recipient) external nonReentrant returns (uint256 liquidity) {
        uint256 balance0 = IERC20Minimal(token0).balanceOf(address(this));
        uint256 balance1 = IERC20Minimal(token1).balanceOf(address(this));
        uint256 amount0 = balance0 - reserve0;
        uint256 amount1 = balance1 - reserve1;

        uint256 _totalSupply = totalSupply;
        if (_totalSupply == 0) {
            liquidity = _sqrt(amount0 * amount1);
            require(liquidity > 1000, "GiwaPool: MINIMUM_LIQUIDITY_REQUIRED");
            _mintLP(address(0xdead), 1000); // Lock initial minimum liquidity
            liquidity -= 1000;
        } else {
            uint256 liquidity0 = (amount0 * _totalSupply) / reserve0;
            uint256 liquidity1 = (amount1 * _totalSupply) / reserve1;
            liquidity = liquidity0 < liquidity1 ? liquidity0 : liquidity1;
        }

        require(liquidity > 0, "GiwaPool: INSUFFICIENT_LIQUIDITY_MINTED");
        _mintLP(recipient, liquidity);
        _update(balance0, balance1);
        emit Mint(msg.sender, recipient, amount0, amount1, liquidity);
    }

    function burn(address recipient) external nonReentrant returns (uint256 amount0, uint256 amount1) {
        uint256 balance0 = IERC20Minimal(token0).balanceOf(address(this));
        uint256 balance1 = IERC20Minimal(token1).balanceOf(address(this));
        uint256 liquidity = balanceOf[address(this)];

        uint256 _totalSupply = totalSupply;
        amount0 = (liquidity * balance0) / _totalSupply;
        amount1 = (liquidity * balance1) / _totalSupply;
        require(amount0 > 0 && amount1 > 0, "GiwaPool: INSUFFICIENT_LIQUIDITY_BURNED");

        _burnLP(address(this), liquidity);
        _safeTransfer(token0, recipient, amount0);
        _safeTransfer(token1, recipient, amount1);

        balance0 = IERC20Minimal(token0).balanceOf(address(this));
        balance1 = IERC20Minimal(token1).balanceOf(address(this));
        _update(balance0, balance1);
        emit Burn(msg.sender, recipient, amount0, amount1, liquidity);
    }

    function swap(
        uint256 amount0Out,
        uint256 amount1Out,
        address recipient,
        bytes calldata /* data */
    ) external nonReentrant {
        require(amount0Out > 0 || amount1Out > 0, "GiwaPool: INSUFFICIENT_OUTPUT_AMOUNT");
        uint112 _reserve0 = reserve0;
        uint112 _reserve1 = reserve1;
        require(amount0Out < _reserve0 && amount1Out < _reserve1, "GiwaPool: INSUFFICIENT_LIQUIDITY");

        if (amount0Out > 0) _safeTransfer(token0, recipient, amount0Out);
        if (amount1Out > 0) _safeTransfer(token1, recipient, amount1Out);

        uint256 balance0 = IERC20Minimal(token0).balanceOf(address(this));
        uint256 balance1 = IERC20Minimal(token1).balanceOf(address(this));

        uint256 amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
        uint256 amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
        require(amount0In > 0 || amount1In > 0, "GiwaPool: INSUFFICIENT_INPUT_AMOUNT");

        // Verify invariant with fee deduction
        {
            uint256 feeMultiplier = 10000 - feeBps;
            uint256 balance0Adjusted = (balance0 * 10000) - (amount0In * feeBps);
            uint256 balance1Adjusted = (balance1 * 10000) - (amount1In * feeBps);
            require(
                balance0Adjusted * balance1Adjusted >= uint256(_reserve0) * uint256(_reserve1) * (10000**2),
                "GiwaPool: K_INVARIANT_VIOLATED"
            );
        }

        _update(balance0, balance1);
        emit Swap(msg.sender, recipient, amount0In, amount1In, amount0Out, amount1Out, feeBps);
    }

    function skim(address recipient) external nonReentrant {
        _safeTransfer(token0, recipient, IERC20Minimal(token0).balanceOf(address(this)) - reserve0);
        _safeTransfer(token1, recipient, IERC20Minimal(token1).balanceOf(address(this)) - reserve1);
    }

    function sync() external nonReentrant {
        _update(IERC20Minimal(token0).balanceOf(address(this)), IERC20Minimal(token1).balanceOf(address(this)));
    }

    function _sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

contracts/GiwaRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IGiwaPool.sol";
import "./interfaces/IGiwaFactory.sol";

interface IWETH {
    function deposit() external payable;
    function transfer(address to, uint256 value) external returns (bool);
    function withdraw(uint256) external;
}

/// @title GiwaRouter
/// @notice Universal Router for executing multi-hop swaps and liquidity provisioning on Giwa Chain.
contract GiwaRouter {
    address public immutable factory;
    address public immutable WETH;

    modifier ensure(uint256 deadline) {
        require(deadline >= block.timestamp, "GiwaRouter: EXPIRED");
        _;
    }

    constructor(address _factory, address _WETH) {
        factory = _factory;
        WETH = _WETH;
    }

    receive() external payable {
        assert(msg.sender == WETH); // Only accept ETH via fallback from the WETH contract
    }

    function _safeTransferFrom(address token, address from, address to, uint256 value) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0x23b872dd, from, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "GiwaRouter: TRANSFER_FROM_FAILED");
    }

    function _safeTransfer(address token, address to, uint256 value) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0xa9059cbb, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "GiwaRouter: TRANSFER_FAILED");
    }

    function _safeTransferETH(address to, uint256 value) internal {
        (bool success, ) = to.call{value: value}(new bytes(0));
        require(success, "GiwaRouter: ETH_TRANSFER_FAILED");
    }

    // ==========================================
    // LIQUIDITY PROVISIONING
    // ==========================================

    function addLiquidity(
        address tokenA,
        address tokenB,
        bool isStable,
        uint256 feeBps,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        address pool = IGiwaFactory(factory).getPool(tokenA, tokenB, isStable);
        if (pool == address(0)) {
            pool = IGiwaFactory(factory).createPool(tokenA, tokenB, isStable, feeBps);
        }

        (uint256 reserveA, uint256 reserveB, ) = IGiwaPool(pool).getReserves();
        if (reserveA == 0 && reserveB == 0) {
            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint256 amountBOptimal = (amountADesired * reserveB) / reserveA;
            if (amountBOptimal <= amountBDesired) {
                require(amountBOptimal >= amountBMin, "GiwaRouter: INSUFFICIENT_B_AMOUNT");
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint256 amountAOptimal = (amountBDesired * reserveA) / reserveB;
                assert(amountAOptimal <= amountADesired);
                require(amountAOptimal >= amountAMin, "GiwaRouter: INSUFFICIENT_A_AMOUNT");
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }

        _safeTransferFrom(tokenA, msg.sender, pool, amountA);
        _safeTransferFrom(tokenB, msg.sender, pool, amountB);
        liquidity = IGiwaPool(pool).mint(to);
    }

    function addLiquidityETH(
        address token,
        bool isStable,
        uint256 feeBps,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable ensure(deadline) returns (uint256 amountToken, uint256 amountETH, uint256 liquidity) {
        address pool = IGiwaFactory(factory).getPool(token, WETH, isStable);
        if (pool == address(0)) {
            pool = IGiwaFactory(factory).createPool(token, WETH, isStable, feeBps);
        }

        (uint256 reserveToken, uint256 reserveETH, ) = IGiwaPool(pool).getReserves();
        if (reserveToken == 0 && reserveETH == 0) {
            (amountToken, amountETH) = (amountTokenDesired, msg.value);
        } else {
            uint256 amountETHOptimal = (amountTokenDesired * reserveETH) / reserveToken;
            if (amountETHOptimal <= msg.value) {
                require(amountETHOptimal >= amountETHMin, "GiwaRouter: INSUFFICIENT_ETH_AMOUNT");
                (amountToken, amountETH) = (amountTokenDesired, amountETHOptimal);
            } else {
                uint256 amountTokenOptimal = (msg.value * reserveToken) / reserveETH;
                assert(amountTokenOptimal <= amountTokenDesired);
                require(amountTokenOptimal >= amountTokenMin, "GiwaRouter: INSUFFICIENT_TOKEN_AMOUNT");
                (amountToken, amountETH) = (amountTokenOptimal, msg.value);
            }
        }

        _safeTransferFrom(token, msg.sender, pool, amountToken);
        IWETH(WETH).deposit{value: amountETH}();
        assert(IWETH(WETH).transfer(pool, amountETH));
        liquidity = IGiwaPool(pool).mint(to);

        if (msg.value > amountETH) {
            _safeTransferETH(msg.sender, msg.value - amountETH);
        }
    }

    function removeLiquidity(
        address tokenA,
        address tokenB,
        bool isStable,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) public ensure(deadline) returns (uint256 amountA, uint256 amountB) {
        address pool = IGiwaFactory(factory).getPool(tokenA, tokenB, isStable);
        require(pool != address(0), "GiwaRouter: POOL_NOT_FOUND");
        _safeTransferFrom(pool, msg.sender, pool, liquidity);
        (uint256 amount0, uint256 amount1) = IGiwaPool(pool).burn(to);
        (address token0, ) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        require(amountA >= amountAMin, "GiwaRouter: INSUFFICIENT_A_AMOUNT");
        require(amountB >= amountBMin, "GiwaRouter: INSUFFICIENT_B_AMOUNT");
    }

    function removeLiquidityETH(
        address token,
        bool isStable,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) public ensure(deadline) returns (uint256 amountToken, uint256 amountETH) {
        (amountToken, amountETH) = removeLiquidity(
            token,
            WETH,
            isStable,
            liquidity,
            amountTokenMin,
            amountETHMin,
            address(this),
            deadline
        );
        _safeTransfer(token, to, amountToken);
        IWETH(WETH).withdraw(amountETH);
        _safeTransferETH(to, amountETH);
    }

    // ==========================================
    // SWAP ROUTING
    // ==========================================

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        bool[] calldata isStablePath,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        amounts = getAmountsOut(amountIn, path, isStablePath);
        require(amounts[amounts.length - 1] >= amountOutMin, "GiwaRouter: INSUFFICIENT_OUTPUT_AMOUNT");

        address firstPool = IGiwaFactory(factory).getPool(path[0], path[1], isStablePath[0]);
        require(firstPool != address(0), "GiwaRouter: POOL_NOT_FOUND");
        _safeTransferFrom(path[0], msg.sender, firstPool, amounts[0]);

        _swap(amounts, path, isStablePath, to);
    }

    function swapExactETHForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        bool[] calldata isStablePath,
        address to,
        uint256 deadline
    ) external payable ensure(deadline) returns (uint256[] memory amounts) {
        require(path[0] == WETH, "GiwaRouter: INVALID_PATH");
        amounts = getAmountsOut(msg.value, path, isStablePath);
        require(amounts[amounts.length - 1] >= amountOutMin, "GiwaRouter: INSUFFICIENT_OUTPUT_AMOUNT");

        IWETH(WETH).deposit{value: amounts[0]}();
        address firstPool = IGiwaFactory(factory).getPool(path[0], path[1], isStablePath[0]);
        require(firstPool != address(0), "GiwaRouter: POOL_NOT_FOUND");
        assert(IWETH(WETH).transfer(firstPool, amounts[0]));

        _swap(amounts, path, isStablePath, to);
    }

    function swapExactTokensForETH(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        bool[] calldata isStablePath,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        require(path[path.length - 1] == WETH, "GiwaRouter: INVALID_PATH");
        amounts = getAmountsOut(amountIn, path, isStablePath);
        require(amounts[amounts.length - 1] >= amountOutMin, "GiwaRouter: INSUFFICIENT_OUTPUT_AMOUNT");

        address firstPool = IGiwaFactory(factory).getPool(path[0], path[1], isStablePath[0]);
        require(firstPool != address(0), "GiwaRouter: POOL_NOT_FOUND");
        _safeTransferFrom(path[0], msg.sender, firstPool, amounts[0]);

        _swap(amounts, path, isStablePath, address(this));
        IWETH(WETH).withdraw(amounts[amounts.length - 1]);
        _safeTransferETH(to, amounts[amounts.length - 1]);
    }

    function _swap(
        uint256[] memory amounts,
        address[] memory path,
        bool[] memory isStablePath,
        address _to
    ) internal {
        for (uint256 i = 0; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            address pool = IGiwaFactory(factory).getPool(input, output, isStablePath[i]);
            address token0 = IGiwaPool(pool).token0();
            uint256 amountOut = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOut) : (amountOut, uint256(0));
            address recipient = i < path.length - 2
                ? IGiwaFactory(factory).getPool(output, path[i + 2], isStablePath[i + 1])
                : _to;
            IGiwaPool(pool).swap(amount0Out, amount1Out, recipient, new bytes(0));
        }
    }

    function getAmountsOut(
        uint256 amountIn,
        address[] memory path,
        bool[] memory isStablePath
    ) public view returns (uint256[] memory amounts) {
        require(path.length >= 2, "GiwaRouter: INVALID_PATH");
        amounts = new uint256[](path.length);
        amounts[0] = amountIn;
        for (uint256 i = 0; i < path.length - 1; i++) {
            address pool = IGiwaFactory(factory).getPool(path[i], path[i + 1], isStablePath[i]);
            require(pool != address(0), "GiwaRouter: POOL_NOT_FOUND");
            amounts[i + 1] = IGiwaPool(pool).getAmountOut(amounts[i], path[i]);
        }
    }
}

contracts/governance/EmergencyGuardian.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title EmergencyGuardian
/// @notice Multi-Sig circuit breaker contract allowing granular pool pause and emergency stop without freezing the entire protocol.
contract EmergencyGuardian {
    address public multiSigAdmin;
    mapping(address => bool) public isPoolPaused;
    mapping(address => bool) public isGuardian;

    event PoolPaused(address indexed pool, address indexed triggeredBy);
    event PoolUnpaused(address indexed pool, address indexed triggeredBy);
    event GuardianStatusSet(address indexed guardian, bool active);
    event MultiSigAdminUpdated(address indexed newAdmin);

    modifier onlyAdmin() {
        require(msg.sender == multiSigAdmin, "Guardian: FORBIDDEN_ADMIN");
        _;
    }

    modifier onlyGuardianOrAdmin() {
        require(msg.sender == multiSigAdmin || isGuardian[msg.sender], "Guardian: FORBIDDEN_GUARDIAN");
        _;
    }

    constructor(address _multiSigAdmin) {
        require(_multiSigAdmin != address(0), "Guardian: ZERO_ADMIN");
        multiSigAdmin = _multiSigAdmin;
    }

    function setGuardian(address guardian, bool active) external onlyAdmin {
        require(guardian != address(0), "Guardian: ZERO_ADDRESS");
        isGuardian[guardian] = active;
        emit GuardianStatusSet(guardian, active);
    }

    function pausePool(address pool) external onlyGuardianOrAdmin {
        require(!isPoolPaused[pool], "Guardian: ALREADY_PAUSED");
        isPoolPaused[pool] = true;
        emit PoolPaused(pool, msg.sender);
    }

    function unpausePool(address pool) external onlyAdmin {
        require(isPoolPaused[pool], "Guardian: NOT_PAUSED");
        isPoolPaused[pool] = false;
        emit PoolUnpaused(pool, msg.sender);
    }

    function setMultiSigAdmin(address newAdmin) external onlyAdmin {
        require(newAdmin != address(0), "Guardian: ZERO_ADMIN");
        multiSigAdmin = newAdmin;
        emit MultiSigAdminUpdated(newAdmin);
    }
}

