// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title GiwaTimelockController
/// @notice 48-hour Timelock controller enforcing execution delay on administrative and fee adjustments.
contract GiwaTimelockController {
    uint256 public constant MIN_DELAY = 48 hours;
    uint256 public constant MAX_DELAY = 30 days;

    address public admin;
    uint256 public delay;

    mapping(bytes32 => bool) public queuedTransactions;

    event TransactionQueued(bytes32 indexed txHash, address indexed target, uint256 value, string signature, bytes data, uint256 eta);
    event TransactionExecuted(bytes32 indexed txHash, address indexed target, uint256 value, string signature, bytes data, uint256 eta);
    event TransactionCancelled(bytes32 indexed txHash);
    event DelayUpdated(uint256 newDelay);
    event AdminUpdated(address newAdmin);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Timelock: FORBIDDEN");
        _;
    }

    modifier onlyTimelock() {
        require(msg.sender == address(this), "Timelock: CALL_MUST_COME_FROM_TIMELOCK");
        _;
    }

    constructor(address _admin, uint256 _delay) {
        require(_admin != address(0), "Timelock: ZERO_ADMIN");
        require(_delay >= MIN_DELAY && _delay <= MAX_DELAY, "Timelock: INVALID_DELAY");
        admin = _admin;
        delay = _delay;
    }

    function queueTransaction(
        address target,
        uint256 value,
        string calldata signature,
        bytes calldata data,
        uint256 eta
    ) external onlyAdmin returns (bytes32 txHash) {
        require(eta >= block.timestamp + delay, "Timelock: ETA_TOO_SOON");

        txHash = keccak256(abi.encode(target, value, signature, data, eta));
        require(!queuedTransactions[txHash], "Timelock: ALREADY_QUEUED");

        queuedTransactions[txHash] = true;
        emit TransactionQueued(txHash, target, value, signature, data, eta);
    }

    function cancelTransaction(bytes32 txHash) external onlyAdmin {
        require(queuedTransactions[txHash], "Timelock: NOT_QUEUED");
        queuedTransactions[txHash] = false;
        emit TransactionCancelled(txHash);
    }

    function executeTransaction(
        address target,
        uint256 value,
        string calldata signature,
        bytes calldata data,
        uint256 eta
    ) external payable onlyAdmin returns (bytes memory) {
        bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
        require(queuedTransactions[txHash], "Timelock: NOT_QUEUED");
        require(block.timestamp >= eta, "Timelock: TRANSACTION_STILL_LOCKED");
        require(block.timestamp <= eta + 14 days, "Timelock: TRANSACTION_EXPIRED");

        queuedTransactions[txHash] = false;

        bytes memory callData;
        if (bytes(signature).length == 0) {
            callData = data;
        } else {
            callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
        }

        (bool success, bytes memory returnData) = target.call{value: value}(callData);
        require(success, "Timelock: TRANSACTION_EXECUTION_REVERTED");

        emit TransactionExecuted(txHash, target, value, signature, data, eta);
        return returnData;
    }

    function setDelay(uint256 newDelay) external onlyTimelock {
        require(newDelay >= MIN_DELAY && newDelay <= MAX_DELAY, "Timelock: INVALID_DELAY");
        delay = newDelay;
        emit DelayUpdated(newDelay);
    }

    function setAdmin(address newAdmin) external onlyTimelock {
        require(newAdmin != address(0), "Timelock: ZERO_ADMIN");
        admin = newAdmin;
        emit AdminUpdated(newAdmin);
    }
}

contracts/governance/ProtocolFeeVault.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IProtocolFeeVault.sol";

interface IERC20Transferable {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

/// @title ProtocolFeeVault
/// @notice Manages protocol fee accumulation and automated distribution on Giwa Chain.
/// @dev Default split: 70% Liquidity Providers, 20% Protocol-Owned Liquidity (POL) Treasury, 10% Burn / Staking.
contract ProtocolFeeVault is IProtocolFeeVault {
    address public owner;
    address public override treasury;

    uint256 public override lpShareBps = 7000;       // 70.00%
    uint256 public override treasuryShareBps = 2000; // 20.00%
    uint256 public override burnShareBps = 1000;     // 10.00%
    uint256 public constant BPS_DENOMINATOR = 10000;

    address public constant DEAD_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    modifier onlyOwner() {
        require(msg.sender == owner, "FeeVault: FORBIDDEN");
        _;
    }

    constructor(address _treasury) {
        require(_treasury != address(0), "FeeVault: ZERO_ADDRESS");
        owner = msg.sender;
        treasury = _treasury;
    }

    function setTreasury(address _newTreasury) external override onlyOwner {
        require(_newTreasury != address(0), "FeeVault: ZERO_ADDRESS");
        treasury = _newTreasury;
        emit TreasuryUpdated(_newTreasury);
    }

    function setShares(
        uint256 _lpBps,
        uint256 _treasuryBps,
        uint256 _burnBps
    ) external override onlyOwner {
        require(_lpBps + _treasuryBps + _burnBps == BPS_DENOMINATOR, "FeeVault: INVALID_SUM");
        lpShareBps = _lpBps;
        treasuryShareBps = _treasuryBps;
        burnShareBps = _burnBps;
        emit SharesUpdated(_lpBps, _treasuryBps, _burnBps);
    }

    function distributeFees(address token)
        external
        override
        returns (uint256 lpAmount, uint256 treasuryAmount, uint256 burnAmount)
    {
        uint256 balance = IERC20Transferable(token).balanceOf(address(this));
        require(balance > 0, "FeeVault: NO_FEES_TO_DISTRIBUTE");

        treasuryAmount = (balance * treasuryShareBps) / BPS_DENOMINATOR;
        burnAmount = (balance * burnShareBps) / BPS_DENOMINATOR;
        lpAmount = balance - treasuryAmount - burnAmount;

        if (treasuryAmount > 0) {
            _safeTransfer(token, treasury, treasuryAmount);
        }
        if (burnAmount > 0) {
            _safeTransfer(token, DEAD_ADDRESS, burnAmount);
        }
        // lpAmount is retained for dynamic LP reward streaming or routed to gauge distributor

        emit FeesDistributed(token, lpAmount, treasuryAmount, burnAmount);
    }

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20Transferable.transfer.selector, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "FeeVault: TRANSFER_FAILED");
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "FeeVault: ZERO_ADDRESS");
        owner = newOwner;
    }
}

contracts/interfaces/IGiwaCLPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title IGiwaCLPool
/// @notice Interface for Giwa Concentrated Liquidity AMM Pools (CLAMM).
interface IGiwaCLPool {
    struct Slot0 {
        uint160 sqrtPriceX96;
        int24 tick;
        uint16 observationIndex;
        uint16 observationCardinality;
        uint16 observationCardinalityNext;
        uint8 feeProtocol;
        bool unlocked;
    }

    event Initialize(uint160 sqrtPriceX96, int24 tick);
    event Mint(
        address sender,
        address indexed owner,
        int24 indexed tickLower,
        int24 indexed tickUpper,
        uint128 amount,
        uint256 amount0,
        uint256 amount1
    );
    event Collect(
        address indexed owner,
        address recipient,
        int24 indexed tickLower,
        int24 indexed tickUpper,
        uint128 amount0,
        uint128 amount1
    );
    event Burn(
        address indexed owner,
        int24 indexed tickLower,
        int24 indexed tickUpper,
        uint128 amount,
        uint256 amount0,
        uint256 amount1
    );
    event Swap(
        address indexed sender,
        address indexed recipient,
        int256 amount0,
        int256 amount1,
        uint160 sqrtPriceX96,
        uint128 liquidity,
        int24 tick
    );
    event Flash(
        address indexed recipient,
        address indexed sender,
        uint256 amount0,
        uint256 amount1,
        uint256 paid0,
        uint256 paid1
    );

    function factory() external view returns (address);
    function token0() external view returns (address);
    function token1() external view returns (address);
    function fee() external view returns (uint24);
    function tickSpacing() external view returns (int24);
    function maxLiquidityPerTick() external view returns (uint128);

    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );

    function initialize(uint160 sqrtPriceX96) external;

    function mint(
        address recipient,
        int24 tickLower,
        int24 tickUpper,
        uint128 amount,
        bytes calldata data
    ) external returns (uint256 amount0, uint256 amount1);

    function collect(
        address recipient,
        int24 tickLower,
        int24 tickUpper,
        uint128 amount0Requested,
